import{c as n,U as t,j as i,g as s,o as r,a6 as o,n as l}from"./chunks/framework.h4W4t1IS.js";const q=JSON.parse('{"title":"Fusion (merge vs squash)","description":"","frontmatter":{"title":"Fusion (merge vs squash)","status":"ready","tags":["git","git-base","all"],"authors":["Jean-François Dion"],"reviewers":[]},"headers":[],"relativePath":"git/fusion.md","filePath":"git/fusion.md"}'),p={name:"git/fusion.md"},u={id:"frontmatter-title",tabindex:"-1"};function c(a,e,d,h,g,m){return t(),i("div",null,[s("h1",u,[r(o(a.$frontmatter.title)+" ",1),e[0]||(e[0]=s("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1))]),e[1]||(e[1]=l(`<p>La <strong><a href="/420-w30-sf-po2/lexique.html#fusion" class="lexicon-link" title="Intégration des commits d&#39;une branche dans une autre. Le merge classique conserve tous les commits; le squash and merge les regroupe en un seul.">fusion</a></strong> (<em>merge</em>) intègre les commits d&#39;une branche dans une autre. Deux <a href="/420-w30-sf-po2/lexique.html#strategie" class="lexicon-link" title="Patron de conception qui permet de définir une famille d&#39;algorithmes, de les encapsuler et de les rendre interchangeables, permettant ainsi de modifier le comportement d&#39;un objet à l&#39;exécution.">stratégies</a> sont courantes : le merge classique et le <em>squash and merge</em>.</p><h2 id="objectifs-d-apprentissage" tabindex="-1">Objectifs d&#39;apprentissage <a class="header-anchor" href="#objectifs-d-apprentissage" aria-label="Permalink to &quot;Objectifs d&#39;apprentissage&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Après cette section, tu seras capable de...</p><ul><li>Différencier merge et squash and merge</li><li>Choisir la stratégie appropriée selon le contexte</li><li>Expliquer comment protéger les branches principales</li></ul></div><h2 id="merge-classique" tabindex="-1">Merge classique <a class="header-anchor" href="#merge-classique" aria-label="Permalink to &quot;Merge classique&quot;">​</a></h2><p>Conserve tous les commits de la branche source dans l&#39;historique de destination.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Avant :</span></span>
<span class="line"><span>develop:     A──B──C</span></span>
<span class="line"><span>                  \\</span></span>
<span class="line"><span>feature:           D──E──F</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Après merge :</span></span>
<span class="line"><span>develop:     A──B──C──D──E──F──G</span></span>
<span class="line"><span>                              ↑</span></span>
<span class="line"><span>                          merge commit</span></span></code></pre></div><p><strong>Avantages :</strong> Historique complet, chaque commit garde son contexte.</p><p><strong>Inconvénients :</strong> L&#39;historique peut devenir encombré si beaucoup de petits commits intermédiaires.</p><h2 id="squash-and-merge" tabindex="-1">Squash and merge <a class="header-anchor" href="#squash-and-merge" aria-label="Permalink to &quot;Squash and merge&quot;">​</a></h2><p>Regroupe tous les commits de la branche en un seul commit dans la destination.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Avant :</span></span>
<span class="line"><span>develop:     A──B──C</span></span>
<span class="line"><span>                  \\</span></span>
<span class="line"><span>feature:           D──E──F</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Après squash and merge :</span></span>
<span class="line"><span>develop:     A──B──C──G</span></span>
<span class="line"><span>                      ↑</span></span>
<span class="line"><span>             un seul commit (D+E+F squashés)</span></span></code></pre></div><p><strong>Avantages :</strong> Historique de <code>develop</code> propre - un commit par fonctionnalité.</p><p><strong>Inconvénients :</strong> L&#39;historique détaillé de la branche est perdu.</p><h2 id="quand-utiliser-quoi" tabindex="-1">Quand utiliser quoi? <a class="header-anchor" href="#quand-utiliser-quoi" aria-label="Permalink to &quot;Quand utiliser quoi?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stratégie</th><th>Cas d&#39;usage</th></tr></thead><tbody><tr><td><strong>Merge</strong></td><td>Branches de longue durée (intégrations majeures), quand l&#39;historique détaillé est important</td></tr><tr><td><strong>Squash and merge</strong></td><td>Branches de fonctionnalité courtes - historique de <code>develop</code> propre</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Standard pour PO2</p><p>Utiliser <strong>Merge</strong> pour les branches de fonctionnalité vers <code>develop</code>. Cela garde l&#39;historique intégral et permet une évaluation juste de l&#39;utilisation faite de git.</p></div><h2 id="sur-github" tabindex="-1">Sur GitHub <a class="header-anchor" href="#sur-github" aria-label="Permalink to &quot;Sur GitHub&quot;">​</a></h2><p>Lors de l&#39;acceptation d&#39;une <a href="/420-w30-sf-po2/lexique.html#pull-request" class="lexicon-link" title="Demande d&#39;intégration d&#39;une branche vers une autre sur GitHub, déclenchant un processus de revue de code par les coéquipiers avant la fusion.">Pull Request</a>, sélectionner <strong>Merge</strong> dans le menu déroulant du bouton &quot;Merge pull request&quot;.</p><div class="danger custom-block"><p class="custom-block-title">Ne pas supprimer la branche pour PO2</p><p>Contrairement à la pratique courante, <strong>ne supprime pas la branche</strong> après la fusion. C&#39;est la seule façon pour la correction de retracer le travail effectué sur chaque branche de fonctionnalité.</p></div><h2 id="proteger-les-branches-principales" tabindex="-1">Protéger les branches principales <a class="header-anchor" href="#proteger-les-branches-principales" aria-label="Permalink to &quot;Protéger les branches principales&quot;">​</a></h2><p><code>main</code> et <code>develop</code> sont des branches permanentes : on doit empêcher qu&#39;un push direct ou accidentel y introduise du code non révisé. Sur GitHub, une règle de protection de branche (<strong>Settings &gt; Branches &gt; Branch protection rules</strong>) permet de :</p><ul><li>Interdire le push direct - tout changement doit passer par une Pull Request</li><li>Exiger au moins une approbation avant la fusion</li><li>Interdire le force-push et la suppression de la branche</li></ul><div class="tip custom-block"><p class="custom-block-title">Standard pour PO2</p><p><code>main</code> et <code>develop</code> sont protégées : aucun push direct, une Pull Request avec au moins une approbation est requise avant la fusion.</p><p>(ne s&#39;applique pas pour les exercices et travaux individuels)</p></div>`,23))])}const f=n(p,[["render",c]]);export{q as __pageData,f as default};
